import request from '@/utils/request'
import store from '../store/index'
import { parseDescription, encodeDescription } from '@/utils/cms'

export default {
    list: function (query) {
        let githubUsername = store.state.configuration.githubUsername
        return request({
            url: `/users/${githubUsername}/gists?page=${query.page}&per_page=${query.pageSize}`
        }).then((response) => {
            let list = response.data
            if (Array.isArray(list)) {
                list = list.map((g) => {
                    let meta = parseDescription(g.description)
                    g.summary = meta.summary
                    g.category = meta.category
                    g.tags = meta.tags
                    g.cover = meta.cover
                    return g
                })
            }
            response.data = list
            return response
        })
    },
    single: function (id) {
        return request({
            url: '/gists/' + id
        }).then((response) => {
            let g = response.data
            let meta = parseDescription(g.description)
            g.summary = meta.summary
            g.category = meta.category
            g.tags = meta.tags
            g.cover = meta.cover
            response.data = g
            return response
        })
    },
    // list 接口单页最多 100 条。详情页需要完整索引来计算上下篇和相关文章。
    listAll: function (pageSize) {
        const size = Math.min(Math.max(parseInt(pageSize || 100, 10), 1), 100)
        const all = []
        const fetchPage = (page) => this.list({ page, pageSize: size }).then((response) => {
            const rows = Array.isArray(response.data) ? response.data : []
            all.push.apply(all, rows)
            if (rows.length < size) return all
            return fetchPage(page + 1)
        })
        return fetchPage(1)
    },

    create: function (form) {
        let files = {}
        files[form.title] = { content: form.content }
        const description = form.category || (form.tags && form.tags.length) || form.cover
            ? encodeDescription(form)
            : (form.description || '')
        return request({
            url: '/gists',
            method: 'post',
            data: {
                "description": description,
                "public": true,
                "files": files
            }
        })
    },
    /**
     * 编辑 gist
     *
     * GitHub 语义: files 里出现的 key 是"最终状态"。
     * 只给新文件名 => 等于新增一个文件, 旧文件仍留在 gist 里,
     * 列表页取 files 的第一个 key 时就会显示旧标题。
     * 所以改名必须把旧文件名显式置为 null(删除)。
     */
    edit: function (form) {
        let files = {}
        let oldTitle = form.originalTitle || form.title
        if (oldTitle !== form.title) {
            files[oldTitle] = null
        }
        files[form.title] = { content: form.content }
        const description = form.category || (form.tags && form.tags.length) || form.cover
            ? encodeDescription(form)
            : (form.description || '')
        return request({
            url: '/gists/' + form.id,
            method: 'PATCH',
            data: {
                "description": description,
                "public": true,
                "files": files
            }
        })
    },
    delete: function (id) {
        return request({
            url: '/gists/' + id,
            method: 'DELETE',
        })
    },
}



